; DSYS.S - SYSTEM PAGE RENDERER
;
; QUERIES DOS_GET_SYSTEM_INFO ($5C) EXACTLY ONCE PER REDRAW AND RENDERS THE
; VALIDATED SNAPSHOT WITH THE WP5 BOUNDED SCREEN PRIMITIVES (SCREENSETCURSOR/
; SCREENPUTSTRING/SCREENPUTCHAR), NOT THE OLD UNBOUNDED PRINTAT. NEVER READS
; PRIVATE OS MEMORY (CURRENTDEVICE, KERNALVIDEOSTD, APTSEG, MCT, VMM STATE)
; DIRECTLY -- ALL DATA COMES FROM THE PUBLIC $5C RECORD.

; QUERYSYSTEMINFO - FILLS SYSINFOBUF FROM DOS_GET_SYSTEM_INFO ($5C).
;
; INPUT: NONE. OUTPUT: C CLEAR = SUCCESS, SYSINFOBUF HOLDS A FRESH 24-BYTE
;        RECORD. C SET = FAILURE, A = OS ERROR CODE, SYSINFOBUF UNCHANGED
;        (THE OS GUARANTEES NO PARTIAL WRITE ON FAILURE).
; CLOBBERS: A, X, Y.
QUERYSYSTEMINFO:
    LDX #<SYSINFOBUF
    LDY #>SYSINFOBUF
    LDA #DOS_GET_SYSTEM_INFO
    JSR OS_API
    RTS

; PRINTDEC16 - FORMATS X/Y (16-BIT VALUE) AS TRIMMED DECIMAL AND WRITES IT AT
; THE CURSOR (ZP CURRENTROW/CURRENTCOL), ADVANCING THE COLUMN BY THE DIGITS WRITTEN.
;
; FORMATDEC16 (DFMT.S) ALWAYS PRODUCES A FIXED 5-BYTE SPACE-PADDED FIELD, NOT
; A TERMINATED STRING -- FINE FOR A GRID BUT NOT FOR AN INLINE SENTENCE, SO
; THIS SKIPS THE LEADING PAD SPACES (NEVER PAST INDEX 4, SO A VALUE OF 0
; STILL PRINTS "0") BEFORE WRITING THE REMAINING DIGITS ONE CHARACTER AT A
; TIME VIA SCREENPUTCHAR (WHICH PRESERVES X), RATHER THAN COMPUTING A
; FMTBUF+SKIP POINTER FOR SCREENPUTSTRING -- NO ADDRESS ARITHMETIC, JUST THE
; SAME INDEXED ADDRESSING THE SKIP SCAN BELOW ALREADY USES. LOCAL TO THIS
; PAGE RENDERER RATHER THAN A DFMT.S ADDITION, SO WP5'S FROZEN FORMATTING
; CONTRACT STAYS UNCHANGED.
;
; INPUT: X/Y = VALUE LOW/HIGH. CURSOR = ZP CURRENTROW (ROW), CURRENTCOL (COL).
; CLOBBERS: A, X, Y.
PRINTDEC16:
    JSR FORMATDEC16
    LDX #0
@SKIP:
    LDA FMTBUF, X
    CMP #SCREENCODE_SPACE
    BNE @FOUND
    INX
    CPX #4
    BCC @SKIP
@FOUND:
    LDA FMTBUF, X
    JSR SCREENPUTCHAR
    INX
    CPX #5
    BCC @FOUND
    RTS

; DSYSSETROW - SETS THE CURSOR TO COLUMN COL_CONTENT, ROW IN A.
; INPUT: A = ROW. CLOBBERS: A, Y. PRESERVES X.
DSYSSETROW:
    TAY
    LDA #COL_CONTENT
    JSR SCREENSETCURSOR
    RTS

; DSYSLABEL - CURSOR TO (COL_CONTENT, A), THEN PRINT THE NUL-TERMINATED
; SCREEN-CODE STRING AT (X,Y), CLAMPED TO THE ROW. THE 12 SYSTEM-PAGE
; ROW RENDERERS ALL OPEN WITH THIS EXACT SEQUENCE (WP5 EXTRACTED IT).
; INPUT: A = ROW, X = STRING PTR LOW, Y = STRING PTR HIGH.
; CLOBBERS: A, X, Y.
DSYSLABEL:
    STX STRINGSRCPTR              ; PARK THE POINTER -- DSYSSETROW CLOBBERS Y
    STY STRINGSRCPTR+1
    JSR DSYSSETROW
    LDA #SCREEN_COLS
    LDX STRINGSRCPTR
    LDY STRINGSRCPTR+1
    JSR SCREENPUTSTRING
    RTS

DSYSRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME

    LDA #ROW_SYS_TITLE
    LDX #<SYSTITLESTR
    LDY #>SYSTITLESTR
    JSR DSYSLABEL

    JSR QUERYSYSTEMINFO
    BCS @FAIL

    ; VALIDATE STRUCTVERSION (OFFSET 0) == 2 AND STRUCTSIZE (OFFSET 1) == 24
    ; BEFORE TRUSTING ANY FIELD (WP6: "VALIDATE STRUCTURE VERSION AND
    ; RETURNED SIZE BEFORE READING FIELDS").
    LDA SYSINFOBUF+SYS_OFF_STRUCTVERSION
    CMP #SYS_STRUCT_VERSION
    BNE @FAIL
    LDA SYSINFOBUF+SYS_OFF_STRUCTSIZE
    CMP #SYS_STRUCT_SIZE
    BNE @FAIL

    JSR DSYSROWVERSION
    JSR DSYSROWDEVICE
    JSR DSYSROWVIDEO
    JSR DSYSROWRANGE
    JSR DSYSROWPROTECTED
    JSR DSYSROWVMM
    JSR DSYSROWPGSIZE
    JSR DSYSROWPGTOTAL
    JSR DSYSROWUSEDFREE
    JSR DSYSROWAPPS
    RTS

@FAIL:
    LDA #ROW_SYS_VERSION
    LDX #<SYSFAILSTR
    LDY #>SYSFAILSTR
    JSR DSYSLABEL
    RTS

; --- OFFSET 2/3/4/22: OSMAJOR/OSMINOR/OSSTAGE/OSPATCH (ROW 6) ---
DSYSROWVERSION:
    LDA #ROW_SYS_VERSION
    LDX #<SYSL_VER
    LDY #>SYSL_VER
    JSR DSYSLABEL

    LDX SYSINFOBUF+SYS_OFF_OSMAJOR          ; OSMAJOR
    LDY #0
    JSR PRINTDEC16
    LDA #SCREENCODE_DOT
    JSR SCREENPUTCHAR

    LDX SYSINFOBUF+SYS_OFF_OSMINOR          ; OSMINOR
    LDY #0
    JSR PRINTDEC16
    LDA #SCREENCODE_DOT
    JSR SCREENPUTCHAR

    LDX SYSINFOBUF+SYS_OFF_OSPATCH         ; OSPATCH
    LDY #0
    JSR PRINTDEC16

    ; OSSTAGE: RELEASE IS THE DEFAULT/EXPECTED CASE AND ADDS NOTHING BY
    ; SAYING SO; ONLY A DEV BUILD IS WORTH FLAGGING.
    LDA SYSINFOBUF+SYS_OFF_OSSTAGE          ; OSSTAGE
    BEQ @DONE
    LDA #SCREEN_COLS
    LDX #<SYSL_DEV_STAGE
    LDY #>SYSL_DEV_STAGE
    JSR SCREENPUTSTRING
@DONE:
    RTS

; --- OFFSET 5: CURRENTDEVICE (ROW 7) ---
DSYSROWDEVICE:
    LDA #ROW_SYS_DEVICE
    LDX #<SYSL_DEVICE
    LDY #>SYSL_DEVICE
    JSR DSYSLABEL

    LDX SYSINFOBUF+SYS_OFF_CURRENTDEVICE
    LDY #0
    JSR PRINTDEC16
    RTS

; --- OFFSET 6: VIDEOSTANDARD (ROW 8) ---
DSYSROWVIDEO:
    LDA #ROW_SYS_VIDEO
    LDX #<SYSL_VIDEO
    LDY #>SYSL_VIDEO
    JSR DSYSLABEL

    LDA SYSINFOBUF+SYS_OFF_VIDEOSTANDARD
    CMP #VIDEO_NTSC
    BEQ @NTSC
    CMP #VIDEO_PAL
    BEQ @PAL
    LDX #<SYSL_UNKNOWN
    LDY #>SYSL_UNKNOWN
    JMP @PRINT
@NTSC:
    LDX #<SYSL_NTSC
    LDY #>SYSL_NTSC
    JMP @PRINT
@PAL:
    LDX #<SYSL_PAL
    LDY #>SYSL_PAL
@PRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 7-10: USERPROGSTART/USERPROGEND (ROW 9) ---
DSYSROWRANGE:
    LDA #ROW_SYS_RANGE
    LDX #<SYSL_RANGE
    LDY #>SYSL_RANGE
    JSR DSYSLABEL

    LDX SYSINFOBUF+SYS_OFF_USERPROGSTART          ; USERPROGSTART LOW
    LDY SYSINFOBUF+SYS_OFF_USERPROGSTART+1          ; USERPROGSTART HIGH
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #SCREEN_COLS
    LDX #<SYSL_DASHDOLLAR
    LDY #>SYSL_DASHDOLLAR
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+SYS_OFF_USERPROGEND           ; USERPROGEND LOW
    LDY SYSINFOBUF+SYS_OFF_USERPROGEND+1          ; USERPROGEND HIGH
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING
    RTS

; --- STATIC (ROW 10) -- $C000-$CFFF IS DOCUMENTED, PUBLICLY-KNOWN MCT/VMM
; WORKSPACE PER THE WP1 CONTRACT, NOT A VALUE READ FROM PRIVATE OS MEMORY.
DSYSROWPROTECTED:
    LDA #ROW_SYS_PROTECTED
    LDX #<SYSL_PROTECTED
    LDY #>SYSL_PROTECTED
    JSR DSYSLABEL
    RTS

; --- OFFSET 11: VMMFLAGS (ROW 11) ---
DSYSROWVMM:
    LDA #ROW_SYS_VMM
    LDX #<SYSL_VMM
    LDY #>SYSL_VMM
    JSR DSYSLABEL

    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_ACTIVE
    BEQ @INACTIVE
    LDX #<SYSL_ACTIVE
    LDY #>SYSL_ACTIVE
    JMP @VMMPRINT
@INACTIVE:
    LDX #<SYSL_INACTIVE
    LDY #>SYSL_INACTIVE
@VMMPRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING

    LDA #SCREEN_COLS
    LDX #<SYSL_REU
    LDY #>SYSL_REU
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_REU_PROBED
    BEQ @UNPROBED
    LDX #<SYSL_PROBED
    LDY #>SYSL_PROBED
    JMP @REUPRINT
@UNPROBED:
    LDX #<SYSL_UNPROBED
    LDY #>SYSL_UNPROBED
@REUPRINT:
    LDA #SCREEN_COLS
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 12-13: VMMPAGESIZE (ROW 12) -- CAPABILITY-GATED ON VMMFLAGS BIT 0
DSYSROWPGSIZE:
    LDA #ROW_SYS_PGSIZE
    LDX #<SYSL_PGSIZE
    LDY #>SYSL_PGSIZE
    JSR DSYSLABEL

    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_ACTIVE
    BEQ @NA

    LDX SYSINFOBUF+SYS_OFF_VMMPAGESIZE
    LDY SYSINFOBUF+SYS_OFF_VMMPAGESIZE+1
    JSR PRINTDEC16
    LDA #SCREEN_COLS
    LDX #<SYSL_BYTES
    LDY #>SYSL_BYTES
    JSR SCREENPUTSTRING
    RTS
@NA:
    LDA #SCREEN_COLS
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 14-15: VMMTOTALPAGES (ROW 13) -- CAPABILITY-GATED
DSYSROWPGTOTAL:
    LDA #ROW_SYS_PGTOTAL
    LDX #<SYSL_PGTOTAL
    LDY #>SYSL_PGTOTAL
    JSR DSYSLABEL

    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_ACTIVE
    BEQ @NA

    LDX SYSINFOBUF+SYS_OFF_VMMTOTALPAGES
    LDY SYSINFOBUF+SYS_OFF_VMMTOTALPAGES+1
    JSR PRINTDEC16
    RTS
@NA:
    LDA #SCREEN_COLS
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 16-19: VMMALLOCPAGES/VMMFREEPAGES (ROW 14) -- CAPABILITY-GATED
DSYSROWUSEDFREE:
    LDA #ROW_SYS_USEDFREE
    LDX #<SYSL_USEDFREE
    LDY #>SYSL_USEDFREE
    JSR DSYSLABEL

    LDA SYSINFOBUF+SYS_OFF_VMMFLAGS
    AND #SYS_VMMFLAG_ACTIVE
    BEQ @NA

    LDX SYSINFOBUF+SYS_OFF_VMMALLOCPAGES
    LDY SYSINFOBUF+SYS_OFF_VMMALLOCPAGES+1
    JSR PRINTDEC16
    LDA #SCREEN_COLS
    LDX #<SYSL_SLASH
    LDY #>SYSL_SLASH
    JSR SCREENPUTSTRING
    LDX SYSINFOBUF+SYS_OFF_VMMFREEPAGES
    LDY SYSINFOBUF+SYS_OFF_VMMFREEPAGES+1
    JSR PRINTDEC16
    RTS
@NA:
    LDA #SCREEN_COLS
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 20-21: APPMAXSLOTS/APPUSEDSLOTS (ROW 15) -- ALWAYS VALID
; (APPUSEDSLOTS IS A TRUE 0 WHEN THE APP TABLE IS INACTIVE, NOT AN
; UNAVAILABLE VALUE, SO THIS IS NOT CAPABILITY-GATED)
DSYSROWAPPS:
    LDA #ROW_SYS_APPS
    LDX #<SYSL_APPS
    LDY #>SYSL_APPS
    JSR DSYSLABEL

    LDX SYSINFOBUF+SYS_OFF_APPUSEDSLOTS          ; APPUSEDSLOTS
    LDY #0
    JSR PRINTDEC16
    LDA #SCREEN_COLS
    LDX #<SYSL_SLASH
    LDY #>SYSL_SLASH
    JSR SCREENPUTSTRING
    LDX SYSINFOBUF+SYS_OFF_APPMAXSLOTS          ; APPMAXSLOTS
    LDY #0
    JSR PRINTDEC16
    RTS
